// Vérifie la configuration ET le payload AVANT tout appel réseau.
// Objectif : qu'un oubli de configuration produise un message qui dit quoi faire,
// et non un 404 opaque ou une URL « undefined/render/pdf ».

const base = $env.GOTENBERG_API_URL;
if (!base || !/^https?:\/\//.test(base)) {
  throw new Error(
    "GOTENBERG_API_URL absent ou invalide dans l'environnement n8n. " +
    "Ajouter GOTENBERG_API_URL=http://webs.local:3100 dans docker/.env.local, " +
    "puis ./deploy.sh — éditer .env.local sans redéployer n'a aucun effet."
  );
}

const entree = $input.first().json;
const body = entree.body || entree;
const data = body.data || null;

// Route empruntée : /render-pdf exige « template », /torah-pdf a un défaut
// historique (le contrat déjà communiqué au plugin torah ne le mentionnait pas).
const chemin = String(entree.webhookUrl || entree.path || '');
const estGenerique = /render-pdf/.test(chemin);

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  throw new Error('payload invalide : un objet "data" est attendu');
}
if (!body.template && estGenerique) {
  throw new Error(
    'champ requis manquant : "template" (obligatoire sur /webhook/render-pdf). ' +
    'Templates disponibles : GET ' + base.replace(/\/+$/, '') + '/templates'
  );
}
// Contrôles génériques uniquement : le schéma détaillé appartient au template,
// et c'est gotenberg.api qui le connaît. Une seule source de vérité.


// Le contrôle de fond (schéma détaillé, présence d'hébreu) est fait par
// gotenberg.api, qui connaît le schéma du template. On ne le duplique pas ici :
// une seule source de vérité pour la validation.

return [{ json: {
  url: base.replace(/\/+$/, '') + '/render/pdf',
  corps: {
    template: body.template || (estGenerique ? null : 'bavli-visavis'),
    data,
    filename: body.filename || `${data.massekhet}_${data.daf}.pdf`,
  },
  correlation_id: body.correlation_id || null,
} }];

// Restitue à l'appelant l'erreur RÉELLE : message, code et statut HTTP d'origine.
//
// n8n emballe la réponse d'erreur d'un HTTP Request dans une chaîne de la forme
//   404 - "{\"success\":false,\"error\":\"...\",\"error_code\":\"UNKNOWN_TEMPLATE\"}"
// (JSON doublement échappé). Sans désencapsulation, on renverrait « erreur inconnue »
// et un 502 générique — ce qui ferait conclure à tort à une panne, et réessayer.

const item = $input.first().json;

// 1. Retrouver le message, quelle que soit la forme que n8n lui a donnée
let brut = '';
for (const c of [item?.error?.message, item?.message, item?.error?.description,
                 item?.error?.error, typeof item?.error === 'string' ? item.error : null]) {
  if (c) { brut = String(c); break; }
}
if (!brut) brut = 'erreur inconnue';

let message = brut;
let code = 'PDF_GENERATION_FAILED';
let statut = 502;   // défaut : la passerelle n'a pas pu joindre le service

// 2. Statut HTTP émis par gotenberg.api, s'il est présent en tête du message
const mStatut = brut.match(/^\s*(\d{3})\s*-\s*/);
if (mStatut) statut = parseInt(mStatut[1], 10);

// 3. Charge utile JSON de gotenberg.api — d'abord telle quelle, sinon déséchappée
const extraire = (s) => {
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  const bloc = s.slice(i, j + 1);
  for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
    try {
      const o = JSON.parse(essai);
      if (o && (o.error || o.error_code)) return o;
    } catch (e) { /* forme suivante */ }
  }
  return null;
};
const charge = extraire(brut);
if (charge) {
  if (charge.error) message = String(charge.error);
  if (charge.error_code) code = String(charge.error_code);
}

// 4. Erreurs levées AVANT l'appel réseau (node Validate Input) : pas de statut ni de
//    charge utile — ce sont des erreurs de requête ou de configuration.
if (!mStatut && !charge) {
  message = brut.replace(/^Error:\s*/, '');
  if (/GOTENBERG_API_URL/.test(message)) { code = 'CONFIG_MISSING'; statut = 500; }
  else if (/champ requis|payload invalide|template/i.test(message)) { code = 'INVALID_DATA'; statut = 400; }
}

return [{ json: { success: false, error: message.slice(0, 500), error_code: code, http_status: statut } }];
